#include <stdio.h>
int main(void) {
    FILE *f = fopen("/tmp/brocode.txt", "w");
    if (!f) { perror("fopen"); return 1; }
    fprintf(f, "%d %s\n", 1, "Asha");
    fprintf(f, "%d %s\n", 2, "Ravi");
    fclose(f);
    f = fopen("/tmp/brocode.txt", "r");
    if (!f) return 1;
    int id; char name[16];
    while (fscanf(f, "%d %15s", &id, name) == 2) printf("%d:%s\n", id, name);
    fclose(f);
    return 0;
}

#include <stdio.h>
typedef struct { int id; char name[12]; } Rec;
int main(void) {
    Rec r[3] = {{1,"A"},{2,"B"},{3,"C"}};
    FILE *f = fopen("/tmp/rec.bin", "wb");
    if (!f) return 1;
    fwrite(r, sizeof r[0], 3, f);
    fclose(f);
    f = fopen("/tmp/rec.bin", "rb");
    if (!f) return 1;
    fseek(f, 2 * (long)sizeof(Rec), SEEK_SET);
    Rec out;
    if (fread(&out, sizeof out, 1, f) == 1) printf("%d %s\n", out.id, out.name);
    fclose(f);
    return 0;
}
